import{_ as a,o as t,c as r,ae as i}from"./chunks/framework.RRduUuAx.js";const d=JSON.parse('{"title":"Expense Tracker: Koala Membership Service Agreement","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/legal/membership.md","filePath":"v1/en/legal/membership.md"}'),n={name:"v1/en/legal/membership.md"};function o(s,e,l,p,c,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="expense-tracker-koala-membership-service-agreement" tabindex="-1">Expense Tracker: Koala Membership Service Agreement <a class="header-anchor" href="#expense-tracker-koala-membership-service-agreement" aria-label="Permalink to &quot;Expense Tracker: Koala Membership Service Agreement&quot;">​</a></h1><p>Last updated: May 3, 2026</p><p>Effective date: May 3, 2026</p><p>Important notice</p><p>To protect your rights, please read this Agreement carefully before purchasing, renewing, or using the “Expense Tracker: Koala Membership Service” (the “Membership Service”). In particular, please pay attention to clauses on limitation of liability, auto-renewal, cancellation and refunds, and dispute resolution.</p><p>【Acceptance】By tapping to agree and purchasing/renewing the Membership Service, or by otherwise using the Membership Service in any manner, you confirm that you have read, understood, and accepted all terms of this Agreement. This Agreement will be legally binding between you and Expense Tracker: Koala.</p><p>【General terms】This Agreement is a general template and may be updated to reflect changes in applicable laws and regulations, platform rules (such as the Apple App Store), or product features. If you do not agree to this Agreement or any future updates, please stop purchasing or using the Membership Service immediately.</p><hr><h2 id="_1-definitions-and-parties" tabindex="-1">1. Definitions and parties <a class="header-anchor" href="#_1-definitions-and-parties" aria-label="Permalink to &quot;1. Definitions and parties&quot;">​</a></h2><p>1.1 “Expense Tracker: Koala” (or “Koala”, “the App”) refers to the bookkeeping application operated by an independent individual developer and any related services.</p><p>1.2 “Developer” or “Operator” refers to the independent individual developer who provides and operates the App and the Membership Service (the “Developer”).</p><p>1.3 “You” or “User” refers to any natural person who downloads, installs, registers/signs in to, and uses the App and the Membership Service.</p><p>1.4 “Member” refers to a user who has successfully purchased the Membership Service through a supported payment method and is entitled to the corresponding benefits during the valid period.</p><p>1.5 “Platform” refers to the third-party app distribution and payment platform through which you purchase the Membership Service (for example, the Apple App Store). Charges, refunds, invoices/receipts, and related matters are also subject to the Platform’s rules.</p><h2 id="_2-scope-and-changes" tabindex="-1">2. Scope and changes <a class="header-anchor" href="#_2-scope-and-changes" aria-label="Permalink to &quot;2. Scope and changes&quot;">​</a></h2><p>2.1 This Agreement governs your purchase and use of the Membership Service. Together with the App’s Terms and Privacy Policy, it forms the complete agreement framework. If there is any inconsistency, this Agreement prevails for matters relating to the Membership Service; otherwise, the relevant agreements and Platform rules apply.</p><p>2.2 The Developer may update this Agreement due to legal or regulatory requirements, Platform rules, or business adjustments. The updated version will be displayed in the App or on a related page and will take effect from the date of publication. Continued use of the Membership Service after an update constitutes your acceptance. If you do not agree, you should stop using the Membership Service and cancel your subscription in accordance with the Platform rules.</p><h2 id="_3-membership-service-content" tabindex="-1">3. Membership Service content <a class="header-anchor" href="#_3-membership-service-content" aria-label="Permalink to &quot;3. Membership Service content&quot;">​</a></h2><p>3.1 The Membership Service is a digital service that unlocks or enhances certain in-app features. Membership benefits are described on the in-app “Membership/Unlock Membership” page and may include, without limitation:</p><ul><li>Quick entry features</li><li>Multi-ledger support</li><li>Cloud sync features</li><li>Multi-currency support</li><li>Export features</li><li>Split-bill features</li><li>Reimbursement-related features</li></ul><p>3.2 The Membership Service is not financial, investment, tax, audit, or accounting advice. Any statistics, reports, exchange-rate conversions, exports, and similar functions are provided as tools only. The Developer does not guarantee suitability, completeness, or timeliness.</p><p>3.3 Membership benefits may change as the product evolves (added, adjusted, discontinued, or made subject to conditions). The Developer will provide reasonable notice for material changes where appropriate. You acknowledge that such changes do not necessarily constitute a breach or an entitlement to a refund.</p><h2 id="_4-purchase-term-and-pricing" tabindex="-1">4. Purchase, term, and pricing <a class="header-anchor" href="#_4-purchase-term-and-pricing" aria-label="Permalink to &quot;4. Purchase, term, and pricing&quot;">​</a></h2><p>4.1 You can purchase the Membership Service via the in-app purchase entry. Available plans may include monthly and annual options; the purchase page controls.</p><p>4.2 Pricing is displayed by the Platform and the final amount charged is determined by the Platform. Prices may vary by region, currency, and tax rules.</p><p>4.3 Benefits take effect upon successful confirmation by the Platform. The membership term is determined by your order/subscription status on the Platform.</p><p>4.4 If you change devices or reinstall the App, you may restore your purchase (for example, via “Restore Purchases”) as long as you are signed in with the same Platform account and meet the Platform’s rules.</p><h2 id="_5-auto-renewal-subscription" tabindex="-1">5. Auto-renewal (subscription) <a class="header-anchor" href="#_5-auto-renewal-subscription" aria-label="Permalink to &quot;5. Auto-renewal (subscription)&quot;">​</a></h2><p>5.1 If you purchase an auto-renewing subscription, the Platform will attempt to charge your selected payment method before the end of each billing cycle and extend your membership accordingly. Charging time, charging method, and handling of renewal failures are governed by the Platform rules.</p><p>5.2 You can cancel auto-renewal in the Platform’s subscription management. After cancellation, you will continue to enjoy benefits until the end of the current paid period, and the subscription will not renew.</p><p>5.3 The typical path on Apple devices is: Settings → Apple ID → Subscriptions (subject to system version). Any “Manage Subscription” entry provided in the App is only a convenience link and does not change the Platform’s final processing.</p><h2 id="_6-cancellation-and-refunds" tabindex="-1">6. Cancellation and refunds <a class="header-anchor" href="#_6-cancellation-and-refunds" aria-label="Permalink to &quot;6. Cancellation and refunds&quot;">​</a></h2><p>6.1 The Membership Service is digital content/digital service. Unless otherwise required by applicable law, whether refunds are available, the refund amount, and processing time are determined by the Platform rules. The Developer cannot bypass the Platform to cancel or refund you directly.</p><p>6.2 If you believe there is an abnormal charge, duplicate charge, or missing entitlement, please first check your order/subscription status on the Platform and submit a refund request or appeal via the Platform’s process. You may also contact the Developer using the contact information in Section 12 for troubleshooting assistance.</p><p>6.3 Consequences arising from your cancellation choices (including failure to cancel before renewal or accidental purchases) are generally borne by you, subject to Platform rules and applicable law.</p><h2 id="_7-usage-rules-and-restrictions" tabindex="-1">7. Usage rules and restrictions <a class="header-anchor" href="#_7-usage-rules-and-restrictions" aria-label="Permalink to &quot;7. Usage rules and restrictions&quot;">​</a></h2><p>7.1 The Membership Service is for your personal use within a reasonable scope only. You may not transfer, gift, rent, lend, resell, or use it to provide commercial services to others.</p><p>7.2 You may not obtain or use Membership benefits through cracking, reverse engineering, client tampering, exploiting vulnerabilities, automated scripts, or other improper means.</p><p>7.3 If you violate this Agreement, applicable laws, or Platform rules, the Developer may take measures including limiting features, suspending service, or terminating Membership benefits without prior notice. Any resulting losses are borne by you.</p><h2 id="_8-interruptions-changes-and-termination" tabindex="-1">8. Interruptions, changes, and termination <a class="header-anchor" href="#_8-interruptions-changes-and-termination" aria-label="Permalink to &quot;8. Interruptions, changes, and termination&quot;">​</a></h2><p>8.1 The Developer will make reasonable efforts to maintain continuity and stability, but is not liable for interruptions, delays, malfunctions, or partial unavailability caused by:</p><ul><li>System maintenance, upgrades, repairs, or failures of data centers/networks/third-party services (including cloud services, push services, and payment Platforms)</li><li>Force majeure or government actions</li><li>Your device, OS version, network environment, or permission settings</li></ul><p>8.2 The Developer may change or terminate the Membership Service for security, compliance, or product reasons. If termination affects your ability to use the service, the Developer will provide reasonable notice where feasible. Any billing settlement or refunds remain subject to Platform rules and applicable law.</p><h2 id="_9-data-and-cloud-sync" tabindex="-1">9. Data and cloud sync <a class="header-anchor" href="#_9-data-and-cloud-sync" aria-label="Permalink to &quot;9. Data and cloud sync&quot;">​</a></h2><p>9.1 If cloud sync is included as a Membership benefit, it may rely on third-party capabilities and network conditions. The Developer will make reasonable efforts to keep the feature available but does not guarantee real-time performance, completeness, or error-free results.</p><p>9.2 We recommend that you back up important data regularly. The Developer is not liable to the extent permitted by law for data loss or inconsistency caused by device loss, accidental deletion, network failures, sync conflicts, or third-party service issues.</p><h2 id="_10-intellectual-property" tabindex="-1">10. Intellectual property <a class="header-anchor" href="#_10-intellectual-property" aria-label="Permalink to &quot;10. Intellectual property&quot;">​</a></h2><p>10.1 The App and related content (including software, UI, icons, trademarks, text, algorithms, and data structures) are protected by law. Rights belong to the Developer or other lawful rights holders.</p><p>10.2 Without authorization, you may not copy, modify, distribute, rent, sell, or otherwise infringe these rights.</p><h2 id="_11-disclaimer-and-limitation-of-liability" tabindex="-1">11. Disclaimer and limitation of liability <a class="header-anchor" href="#_11-disclaimer-and-limitation-of-liability" aria-label="Permalink to &quot;11. Disclaimer and limitation of liability&quot;">​</a></h2><p>11.1 To the maximum extent permitted by law, the Developer is not liable for indirect losses, loss of profits, or data loss arising from your use of or inability to use the Membership Service.</p><p>11.2 Where the Developer is liable under this Agreement, the total liability (to the extent permitted by law) is capped at the amount you actually paid for the Membership Service in the most recent billing cycle related to the dispute, unless applicable law provides otherwise.</p><h2 id="_12-contact" tabindex="-1">12. Contact <a class="header-anchor" href="#_12-contact" aria-label="Permalink to &quot;12. Contact&quot;">​</a></h2><p>If you have questions about the Membership Service, subscription, purchase restoration, or benefit issues, please contact the Developer at:</p><ul><li>Email: <a href="mailto:ruanweidev@163.com" target="_blank" rel="noreferrer">ruanweidev@163.com</a></li></ul><h2 id="_13-governing-law-and-dispute-resolution" tabindex="-1">13. Governing law and dispute resolution <a class="header-anchor" href="#_13-governing-law-and-dispute-resolution" aria-label="Permalink to &quot;13. Governing law and dispute resolution&quot;">​</a></h2><p>13.1 The formation, validity, performance, interpretation, and dispute resolution of this Agreement are governed by the laws of the People’s Republic of China (excluding conflict-of-law rules).</p><p>13.2 Any dispute arising from or related to this Agreement should first be resolved through friendly consultation. If consultation fails, either party may file a lawsuit with the competent People’s Court in the Developer’s place of residence.</p><h2 id="_14-miscellaneous" tabindex="-1">14. Miscellaneous <a class="header-anchor" href="#_14-miscellaneous" aria-label="Permalink to &quot;14. Miscellaneous&quot;">​</a></h2><p>14.1 If any provision of this Agreement is held invalid, the remaining provisions remain in effect.</p><p>14.2 Headings are for convenience only and do not affect interpretation.</p><p>14.3 If this Agreement conflicts with Platform rules, Platform rules prevail for payment, renewal, refunds, and subscription status determinations; this Agreement prevails for other matters.</p>',62)])])}const m=a(n,[["render",o]]);export{d as __pageData,m as default};
